import React from 'react';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Button from '@mui/material/Button';
import Box from '@mui/material/Box';
import { Stack } from '@mui/system';

import './Navbar.css';

import { useTranslation } from 'react-i18next';
import i18n from 'i18next';
import { useHistory } from "react-router-dom/cjs/react-router-dom.min";

export default function Navbar() {
    const { t } = useTranslation();
    const history = useHistory();

    const menuItems = [
        { text: t('navbar.home'), link: '/' },
        { text: t('navbar.projects'), link: '/projects' },
        { text: t('navbar.cv'), link: '/cv' },
        { text: t('navbar.contact'), link: '/contact' },
        { text: t('navbar.about'), link: '/about' },
    ];

    const handleTranslate = (lng) => {
        if (i18n.language !== lng) {
            localStorage.setItem('i18nextLng', lng);
            i18n.changeLanguage([lng]);
        }
    };

    return (
        <AppBar position="relative" zIndex={10}>
            <Stack direction="row" className='navbar-container' height={64}>
                <Toolbar className='navbar'>
                    <Box sx={{ display: { xs: 'none', md: 'flex' }, gap: '5vw' }}>
                        {menuItems.map((item) => (
                            <Button color="inherit" key={item.text} className="navbar-button" 
                                onClick={() => history.push(item.link) } >
                                {item.text}
                            </Button>
                        ))}
                    </Box>
                </Toolbar>
                <Button
                    onClick={() => handleTranslate(i18n.language === 'fr' ? 'en' : 'fr')}
                    className="language-button">
                    {t('navbar.language')}
                </Button>
            </Stack>
        </AppBar>
    );
}
