import { Button, Card, CardActions, CardContent, CardMedia, Typography, Box, Stack, Chip, Tooltip, Fade } from '@mui/material';
import i18n from "../../translations/i18n";
import { useHistory } from "react-router-dom/cjs/react-router-dom.min";
import { useProjects } from "../../context/ProjectsContext";

const ProjectCard = ({ project }) => {
    const lang = i18n.language;
    const history = useHistory();
    const { getType } = useProjects();

    const title = project.name[lang];
    const description = project.description[lang];
    const typesIndexes = project.types;
    const types = typesIndexes.map((type) => getType(type));
    const link = project.link || null;
    const techonologies = project.technologies;
    const defaultImage = 'https://images.unsplash.com/photo-1557683316-973673baf926';

    const { type, src } = project.projectCardContent;
    let content = null;
    try {
        content = require(`../../resources/${src}`);
    } catch (error) {
        console.error(error);
    }

    return (
        <Card sx={{ display: 'flex', backgroundColor: '#003d52' }}>
            <Box sx={{ display: 'flex', flexDirection: 'column' }}>
                <CardContent sx={{ flex: '1 0 auto' }} >
                    <Stack direction="column" spacing={1}>
                        <Typography variant="h5" component="div" color={'white'} title={title} >
                            {title}
                        </Typography>
                        <Stack direction="row" spacing={1} useFlexGap flexWrap={"wrap"}>
                            {types.map((type, index) => (
                                <Tooltip 
                                    key={index}
                                    title={type.description[lang]} 
                                    placement="bottom"
                                    arrow
                                    TransitionComponent={Fade}
                                    TransitionProps={{ timeout: 600 }}
                                >
                                    <Chip 
                                        key={index} 
                                        label={type.name[lang]} 
                                        variant="outlined"
                                        style={{ color: "#fff" }}
                                        size='medium' 
                                    />
                                </Tooltip>
                            ))}
                        </Stack>
                        <Stack direction="row" spacing={1} useFlexGap flexWrap={"wrap"}>
                            {techonologies.map((tech, index) => (
                                <Chip key={index} label={tech} variant="outlined" style={{ color: "#fff" }} size='small' />
                            ))}
                        </Stack>
                        <Typography variant="body2" color={'white'} align="justify" >
                            {description}
                        </Typography>
                    </Stack>
                </CardContent>
                {link && (
                    <CardActions>
                        <Button 
                            size="small"
                            onClick={() => 
                                window.open(link, "_blank")
                            }
                            variant='outlined'
                            sx={{ 
                                border: '1px solid #ff5859',
                                backgroundColor: '#0000',
                                color: '#ff5859',
                                transition: 'all 0.5s',
                                '&:hover': {
                                    backgroundColor: '#ff5859',
                                    color: '#003d52',
                                    border: '1px solid #ff5859',
                                }
                            }}
                        >
                            {i18n.t('projects.projectCard.button')}
                        </Button>
                    </CardActions>
                )}
            </Box>
            <CardMedia
                component={(!content || type === 'image') ? 'img' : 'video'}
                sx={{ height: 300, maxWidth: 300 }}
                alt={title}
                style={{
                    objectFit: 'cover',
                    objectPosition: 'center',
                }}
                className="card-media"
                src={content || defaultImage}
                {
                // Auto play video and loop it
                ...(content && type === 'video') && {
                    autoPlay: true,
                    loop: true,
                    muted: true,
                    playsInline: true
                }
                }
            />
        </Card>
    );
}

export default ProjectCard;
